*{box-sizing:border-box} :root{--ink:#25473c;--muted:#779287;--mint:#dcefe1;--deep:#31634f;--cream:#fffdf6;--coral:#f28770;--gold:#e7ad48} html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#dcefe1;color:var(--ink);font-family:'DM Sans',sans-serif;touch-action:none;user-select:none;-webkit-user-select:none} button{font:inherit;color:inherit;border:0;cursor:pointer;-webkit-tap-highlight-color:transparent}.game-shell{height:100dvh;width:100%;max-width:1180px;margin:auto;padding:0 20px;display:flex;flex-direction:column;overflow:hidden}.topbar{height:78px;flex:none;display:flex;align-items:center;justify-content:space-between;padding:0 9px}.brand{display:flex;align-items:center;gap:11px}.brand-mark{width:39px;height:39px;border-radius:14px;background:#f7fff5;display:grid;place-items:center;color:#579b75;font-size:23px;box-shadow:0 4px 12px #39764d12}.brand-name{font:900 20px 'Nunito',sans-serif;letter-spacing:-.7px;line-height:20px}.brand-sub{font-size:8px;letter-spacing:1.55px;color:#719184;font-weight:800;margin-top:3px}.top-actions{display:flex;align-items:center;gap:10px}.orb-pill{height:38px;border:1px solid #c9e0d0;background:#f5fff4;border-radius:22px;display:flex;align-items:center;gap:6px;padding:0 12px;font-size:14px;font-weight:800;box-shadow:0 3px 10px #52775b0c}.orb-icon{color:#75a77c;font-size:17px}.orb-label{font-size:10px;color:#809b8f;font-weight:600}.icon-button{width:40px;height:40px;background:#f5fff4;border:1px solid #c9e0d0;border-radius:14px;position:relative;font-size:18px;color:#47765f;box-shadow:0 3px 10px #52775b0c}.icon-button i{font-style:normal;position:absolute;right:-4px;top:-5px;width:17px;height:17px;border-radius:50%;background:#ee9579;color:white;font-size:10px;font-weight:800;display:grid;place-items:center;border:2px solid #e1f1e4}.play-area{position:relative;flex:1;min-height:180px;border-radius:25px;overflow:hidden;background:#a6cf9d;box-shadow:0 12px 30px #44604b20,inset 0 0 0 1px #ffffff90}#world{width:100%;height:100%;display:block;object-fit:cover}.scene-vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,#244c461d,transparent 19%,transparent 75%,#183f3820)}.location-chip{position:absolute;top:17px;left:18px;height:32px;padding:0 12px;border-radius:20px;background:#fffffff0;box-shadow:0 4px 14px #29563f20;display:flex;align-items:center;gap:8px;font-size:9px;font-weight:800;letter-spacing:1.1px;color:#537b68}.sun-dot{width:7px;height:7px;border-radius:50%;background:#f4bd57;box-shadow:0 0 0 3px #f4bd5728}.chip-divider{height:13px;width:1px;background:#dce9db;margin:0 1px}.location-chip #weather{font-size:10px;letter-spacing:0;color:#83a18e}.quest-card{position:absolute;right:17px;top:16px;min-width:195px;height:54px;border-radius:16px;background:#fffdf2f2;display:flex;align-items:center;padding:0 11px;gap:9px;box-shadow:0 5px 16px #274d3d21;transition:transform .2s}.quest-icon{width:29px;height:29px;border-radius:10px;background:#ffedc5;color:#d29338;display:grid;place-items:center;font-size:17px}.quest-card small,.battle-head small,.journal-head small{display:block;color:#9c9b76;font-weight:800;font-size:8px;letter-spacing:1.25px}.quest-card strong{display:block;margin-top:3px;font-size:11px}.quest-arrow{margin-left:auto;font-size:22px;color:#9bb39e}.bottom-hint{position:absolute;bottom:15px;left:50%;transform:translateX(-50%);white-space:nowrap;border-radius:20px;background:#244c42a8;color:#f5ffe7;padding:8px 13px;font-size:9px;font-weight:800;letter-spacing:1.35px;backdrop-filter:blur(8px)}.hint-key{color:#ffe49b;font-size:13px;margin-right:5px}.controls{height:190px;flex:none;padding:12px 14px 0}.control-tip{height:22px;display:flex;align-items:center;justify-content:center;gap:7px;color:#638271;font-size:11px;font-weight:700}.tip-spark{color:#e5ad4a;font-size:14px}.control-row{height:118px;position:relative;display:flex;align-items:center;justify-content:space-between;padding:0 5px}.dpad{width:120px;height:104px;position:relative;display:grid;grid-template-columns:40px 40px 40px;grid-template-rows:34px 34px 34px;gap:0;touch-action:none}.pad{background:#f6fff4;border:1px solid #c8dfcc;color:#568168;font-size:24px;font-weight:800;box-shadow:0 3px 0 #c2d8c6;touch-action:none}.pad:active,.pad.pressed{background:#d7efd9;transform:translateY(2px);box-shadow:0 1px 0 #c2d8c6}.pad.up{grid-area:1/2;border-radius:12px 12px 5px 5px}.pad.left{grid-area:2/1;border-radius:12px 5px 5px 12px}.pad.right{grid-area:2/3;border-radius:5px 12px 12px 5px}.pad.down{grid-area:3/2;border-radius:5px 5px 12px 12px}.pad-center{grid-area:2/2;display:grid;place-items:center;background:#e8f4e7;color:#9abd9e;font-size:14px}.move-label{position:absolute;left:47px;bottom:0;font-size:8px;font-weight:800;letter-spacing:1.5px;color:#8da79a}.explore-button{display:flex;align-items:center;gap:10px;padding:0 19px;height:55px;min-width:146px;border-radius:19px;background:#346b54;color:#fffef5;box-shadow:0 5px 0 #28553f,0 8px 16px #315c4624;text-align:left;transition:transform .15s,box-shadow .15s}.explore-button:active{transform:translateY(3px);box-shadow:0 2px 0 #28553f}.explore-icon{font-size:22px;color:#ffe9ac}.explore-button b{display:block;font:800 13px 'Nunito',sans-serif}.explore-button small{display:block;font-size:9px;color:#c7e1ca;margin-top:2px}.footer-note{text-align:center;color:#91a99a;font-size:9px;margin-top:1px}.footer-note span{font-size:12px;margin-right:4px}.toast{position:absolute;left:50%;top:77px;transform:translate(-50%,-10px);opacity:0;pointer-events:none;background:#fffdf4;color:#426b53;padding:10px 17px;border-radius:20px;font-size:11px;font-weight:800;box-shadow:0 5px 18px #33593e2b;transition:all .22s;z-index:5;white-space:nowrap}.toast.show{transform:translate(-50%,0);opacity:1}.battle-overlay,.collection-overlay{position:absolute;inset:0;z-index:4;background:#193e35a6;backdrop-filter:blur(5px);display:flex;align-items:center;justify-content:center;padding:18px}.hidden{display:none!important}.battle-scene{width:min(420px,100%);background:#fffdf4;border-radius:25px;box-shadow:0 20px 60px #193a3260;padding:17px 19px 18px;position:relative;overflow:hidden}.battle-scene:before{content:'';position:absolute;top:0;left:0;right:0;height:112px;background:linear-gradient(135deg,#e1f2d9,#f2f4d8);z-index:0}.battle-head,.wild-orbit,.wild-stats,.battle-message,.battle-actions{position:relative;z-index:1}.battle-head{display:flex;align-items:flex-start;justify-content:space-between}.battle-head h2,.journal-head h2{font:900 22px 'Nunito',sans-serif;margin:3px 0;color:#315b45}.battle-head small{color:#7d9d81}.close-battle{width:31px;height:31px;border-radius:11px;background:#ffffffba;color:#73927c;font-size:22px;display:grid;place-items:center;line-height:1}.wild-orbit{height:153px;display:grid;place-items:center}.wild-orbit:before{content:'';position:absolute;width:135px;height:114px;border-radius:50%;background:#f3f5dc;opacity:.72}.wild-shadow{position:absolute;bottom:17px;width:90px;height:18px;border-radius:50%;background:#7d9f6b35;filter:blur(4px)}#wildCanvas{position:relative;width:210px;height:166px;image-rendering:auto;overflow:visible}.sparkle{position:absolute;color:#e0b457;font-size:19px;animation:twinkle 1.8s infinite}.s1{left:28%;top:30%}.s2{right:25%;top:48%;animation-delay:.7s}@keyframes twinkle{50%{opacity:.35;transform:scale(.75) rotate(25deg)}}.wild-stats{margin-top:-3px}.stat-top,.meter-caption{display:flex;justify-content:space-between;align-items:center}.stat-top span,.meter-caption{font-size:8px;font-weight:800;letter-spacing:1px;color:#8ca08b}.stat-top strong{font-size:8px;letter-spacing:1px;color:#d6915e}.meter{height:7px;background:#e6eadb;border-radius:8px;margin:6px 0 4px;overflow:hidden}.meter-fill{height:100%;width:100%;border-radius:8px;background:linear-gradient(90deg,#f1bf65,#ee906f);transition:width .3s}.meter-caption{font-size:8px}.battle-message{min-height:34px;display:flex;align-items:center;justify-content:center;text-align:center;color:#668271;font-size:11px;font-weight:600;padding:7px 3px}.battle-actions{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:5px}.action-button{height:54px;border-radius:15px;display:flex;align-items:center;text-align:left;gap:8px;padding:0 11px;transition:transform .12s}.action-button:active{transform:scale(.97)}.action-button.soothe{background:#edf4e7;color:#4f795a}.action-button.catch{background:#f9e8d8;color:#9a6641}.action-emoji{font-size:19px}.action-button b{display:block;font:800 11px 'Nunito',sans-serif}.action-button small{display:block;font-size:8px;opacity:.75;margin-top:2px}.journal-card{width:min(470px,100%);max-height:100%;overflow:auto;background:#fffdf4;border-radius:25px;padding:21px;box-shadow:0 20px 60px #193a3260}.journal-head{display:flex;align-items:flex-start;justify-content:space-between}.journal-head h2{font-size:24px;margin-top:4px}.journal-intro{font-size:11px;color:#809486;margin:3px 0 16px}.collection-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.creature-card{min-height:96px;border-radius:16px;padding:10px;background:#eef5e9;display:flex;align-items:center;gap:9px;position:relative;overflow:hidden}.creature-card.locked{background:#f1f0e7}.creature-thumb{width:58px;height:62px;border-radius:14px;background:#deefd6;display:grid;place-items:center}.creature-thumb canvas{width:58px;height:58px}.creature-info b{display:block;font:800 11px 'Nunito',sans-serif;color:#456b50}.creature-info small{display:block;color:#91a28e;font-size:8px;margin-top:3px}.creature-count{position:absolute;right:8px;top:7px;background:#fffdf3;border-radius:10px;padding:3px 6px;font-size:8px;font-weight:800;color:#729079}.locked .creature-thumb{filter:grayscale(1);opacity:.48}.locked .creature-info b{color:#9ba69a}.journal-footer{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #edf0e3;padding-top:13px;margin-top:14px;color:#829687;font-size:10px}.journal-footer b{color:#436e51}.journal-footer button{font-size:9px;font-weight:700;color:#9e8d71;background:#f4f0e4;border-radius:10px;padding:8px 10px}
