  function drawCreature(c,spec,cx,cy,scale=1,t=0){const bob=Math.sin(t)*2; c.save();c.translate(cx,cy+bob);c.scale(scale,scale);c.fillStyle='#496d4a25';c.beginPath();c.ellipse(0,29,30,8,0,0,Math.PI*2);c.fill();
